(()=>{const S="تفريغ تعليمي من الفيديو المرفوع: حل وشرح احدث تجميعات اختبار قدرات جامعيين القسم اللفظي - أكاديمية عايد للتدريب";const B=(i,c,q,o,a,e)=>({id:"qdv-jamiin-20260905-"+i,area:"exams",family:"qudurat",subject:"qudurat-verbal",category:c,level:"intermediate",q,options:o,answer:a,explain:e,source:S});window.NEON_UPLOADED_QUDURAT_VERBAL_JAMIIN_20260905=[B("001","sentence-completion","يعد ........ التجاري وسيلة استقطاب جبارة، فالصورة التي تختزلها مساحته لا تحتاج إلى ........ كالكلام.",["الترويج - صياغة","الإعلان - ترجمة","الإبهار - تنسيق","العمل - بلاغة"],1,"الإعلان التجاري يعتمد على الصورة التي تصل دلالتها مباشرة، بخلاف الكلام الذي قد يحتاج إلى ترجمة."),B("002","analogy","روح : جسد",["كلمة : قول","معنى : لفظ","سؤال : اختبار","أسرع : سبق"],1,"العلاقة هي مضمونٌ يتجسد في وعاء؛ فالروح في الجسد تقابل المعنى في اللفظ."),B("003","relation-difference","يفضل عثمان زراعة حبوب الشوفان على الشعير، والرمان على البرتقال، وزهر الأقحوان على ملكة الليل. يمكن القول إن عثمان يفضل:",["الكوسا","الباذنجان","البامية","اليقطين"],1,"الإجابة المعتمدة في شرح الفيديو هي الباذنجان وفق النمط المستنتج من الأمثلة."),B("004","contextual-error","إذا تربى الإنسان في بيئة (سيئة) فإنه يلتقط صورة (جميلة) عن (مجتمعه) ويراها بصورة (إيجابية).",["سيئة","جميلة","مجتمعه","إيجابية"],0,"السياق اللاحق إيجابي؛ لذا كلمة «سيئة» هي غير المنسجمة مع بقية العبارة."),B("005","contextual-error","من المهم بعد الاستغلال التجاري للاختراع الحصول على براءة امتياز. حدد الكلمة غير المناسبة سياقيًا.",["بعد","الاختراع","براءة","التجاري"],0,"الحصول على براءة الاختراع ينبغي أن يسبق الاستغلال التجاري، لذا «بعد» هي غير المناسبة."),B("006","reading-comprehension","قال الميداني في قصة «مجير أم عامر»: خرج قوم للصيد في يوم حار، فعرضت لهم أم عامر وهي الضبع، فطردوها حتى ألجؤوها إلى خباء أعرابي. فقال الأعرابي: «لا تصلون إليها ما ثبت قائم سيفي بيدي». فرجعوا وتركوه، فحلب لها من لقحته وقرب إليها لبنًا وماءً، فأقبلت تلع مرة في هذا ومرة في هذا حتى عاشت واستراحت.\n\nما قصد الأعرابي بقوله: «لا تصلون إليها ما ثبت قائم سيفي بيدي»؟",["حتى أموت","بقدر استطاعتي","ما دمت ممسكًا بسيفي","ليس مما سبق"],2,"المعنى المباشر أنه سيمنعهم منها ما دام قادرًا ممسكًا بسيفه."),B("007","reading-comprehension","قال الميداني في قصة «مجير أم عامر»: خرج قوم للصيد في يوم حار، فعرضت لهم أم عامر وهي الضبع، فطردوها حتى ألجؤوها إلى خباء أعرابي. فقال الأعرابي: «لا تصلون إليها ما ثبت قائم سيفي بيدي». فرجعوا وتركوه، فحلب لها من لقحته وقرب إليها لبنًا وماءً، فأقبلت تلع مرة في هذا ومرة في هذا حتى عاشت واستراحت.\n\nيعرض النص خلقًا محمودًا ومشهورًا عند العرب، ما هو؟",["إجارة المستغيث","الدفاع عن المظلوم","الرفق بالحيوان","الشجاعة والثأر"],0,"الأعرابي آوى الضبع وحماها ممن يطاردها، وهو مثال على إجارة المستغيث."),B("008","reading-comprehension","قال الميداني في قصة «مجير أم عامر»: خرج قوم للصيد في يوم حار، فعرضت لهم أم عامر وهي الضبع، فطردوها حتى ألجؤوها إلى خباء أعرابي. فقال الأعرابي: «لا تصلون إليها ما ثبت قائم سيفي بيدي». فرجعوا وتركوه، فحلب لها من لقحته وقرب إليها لبنًا وماءً، فأقبلت تلع مرة في هذا ومرة في هذا حتى عاشت واستراحت.\n\nجملة «مرة في هذا ومرة في هذا» تعود على:",["الحليب والماء","الماء فقط","الدم والماء","اللقحة والماء"],0,"الضميران يعودان على اللبن والماء اللذين قُدما للضبع."),B("009","relation-difference","خمس أخوات: أمل ونورة ومنال وابتسام وسمر. المعلمة والممرضة مجموع عمريهما ٥٥ سنة. ابتسام وسمر توأم. ابتسام لا تدرس وليس لها محل تجاري، ولا تعمل في الصحة أو التعليم، وليس لها شركة خاصة. نورة أكبر من أمل وسمر وابتسام، ومنال أكبر من نورة. المحاسبة توأم سمر. ابتسام أكبر من أمل بثلاث سنوات، والطبيبة عمرها عدد فردي. من أكبر الأخوات سنًا؟",["منال","أمل","سمر","نورة"],0,"المعطيات تنص على أن منال أكبر من نورة، ونورة أكبر من أمل وسمر وابتسام؛ إذن منال هي الأكبر."),B("010","reading-comprehension","اغتنم الفرص، فإن الفرص إذا ذهبت لا تأتي مرة أخرى. يفهم من العبارة أن الفرص:",["لا تتكرر","تكون كالغيم","تتكرر","تبقى"],0,"العبارة تصرح بأن الفرص إذا فاتت لا تعود، أي لا تتكرر."),B("011","analogy","الخامس : السادس",["ليمون : برتقال","عنب : زبيب","جرجير : تفاح","مد : طويل"],1,"الإجابة المعتمدة في شرح الفيديو هي «عنب : زبيب»."),B("012","contextual-error","امشِ إلى أهدافك بخطوات حثيثة، وفُلَّ عضديك بالعزيمة والصبر. حدد الكلمة غير المناسبة سياقيًا.",["حثيثة","فُلَّ","عضديك","الصبر"],1,"«فُلَّ» تعني أضعف أو اكسر، وهي تناقض معنى تقوية العزم؛ لذا هي غير المناسبة."),B("013","analogy","فرشاة : معجون",["موقد : شعلة","دخان : رماد","حطب : خشب","عود : ثقاب"],0,"الفرشاة تُستخدم مع المعجون، كما يرتبط الموقد بالشعلة في الاستخدام."),B("014","contextual-error","جلس سالم يتأمل السواحل الجميلة في بلاده، ولكنه تحسر لأنه لا يستطيع الوصول إليها لصغر سنه وبعدها عن خياله. حدد الكلمة غير المناسبة سياقيًا.",["تحسر","صغر","بعدها","خياله"],3,"البعد يكون عن مكانه لا عن «خياله»، لذا كلمة «خياله» غير مناسبة في السياق."),B("015","analogy","أبوة : عمومة",["أمومة : خؤولة","قرابة : نسب","خؤولة : أخ الأم","إصبع : قدم"],0,"الأبوة والعمومة قرابتان من جهة الأب، وتقابلهما الأمومة والخؤولة من جهة الأم."),B("016","analogy","ثوب : نسيج",["قلم : حبر","بحر : حبر","باب : خشب","جلد : قربة"],2,"الثوب يُصنع من النسيج، كما يُصنع الباب من الخشب."),B("017","reading-comprehension","خطط أب لرحلة سياحية إلى مدينة، وعند وصول الأسرة وجدوا المدينة مزدحمة وأماكن السكن ممتلئة. ما الخطأ الذي وقع فيه الأب؟",["لم يحجز من مكتب سياحي","لم يشرك عائلته بالقرار","وقت الرحلة كان خطأ","السياحة الخارجية مكلفة بالنسبة له"],2,"ازدحام المدينة وامتلاء السكن يشيران إلى سوء اختيار توقيت الرحلة."),B("018","reading-comprehension","منعت شركة التدخين في مكان العمل، فأصبح المدخن يخرج من مكان العمل ليدخن خارجه. ما النتيجة التي يمكن استنتاجها؟",["التدخين خارج المكتب يؤدي إلى تأخير وتعطيل العمل","التدخين خارج العمل أكثر ضررًا من التدخين داخل العمل","الشركة تريد التوعية بأضرار التدخين وذلك في غرفة التدخين","التدخين خارج المكتب غير حضاري"],0,"خروج الموظف من مكان العمل للتدخين يستهلك وقت العمل، فيؤدي إلى التأخير والتعطيل."),B("019","relation-difference","شهد أربعة أشخاص على لوحة سيارة، فاتفقوا أن أول حرف فيها «ر». وقال ثلاثة منهم إن نهاية اللوحة «٥٧»، وظن ثلاثة أن الحرف الثاني «ح»، وذكروا أن الثالث والرابع على الترتيب «ص، ٢». أي لوحات السيارة التالية توافق أقوال الشهود؟",["ر ح ص ٥٧٢","ر ص ح ٥٧٢","ر ح ص ٢٥٧","ح ر ص ٧٥٢"],2,"بتجميع الشهادات: الأول ر، الثاني ح، الثالث ص، الرابع ٢، والنهاية ٥٧؛ فتكون «ر ح ص ٢٥٧»."),B("020","reading-comprehension","إن الخياطة على الحرير أمر صعب ويحتاج دقة وتركيز، كما أن الحرير سعره وتكلفته عالية جدًا. مما سبق نستفيد أن:",["الخياطة على الحرير فن قديم","الخياطة على الحرير تحتاج تركيزًا ودقة","الطلب على الحرير وذلك لعلو سعره","الخياطة تقتصر فقط على النساء"],1,"النص يذكر صراحة أن الخياطة على الحرير تحتاج إلى الدقة والتركيز."),B("021","contextual-error","أكل الطعام عند الجوع يفسد المعدة. حدد الكلمة غير المناسبة سياقيًا.",["الطعام","الجوع","يفسد","المعدة"],2,"الأكل عند الجوع أمر طبيعي، لذا «يفسد» لا تنسجم مع المعنى المقصود."),B("022","sentence-completion","من السهل أن نتفادى مسؤولياتنا، ولكن لن نستطيع أن نتفادى ......",["مشاكلها","خطورتها","نتائجها","مكوناتها"],2,"قد يتهرب الإنسان من المسؤولية لكنه لا يستطيع الهروب من نتائجها."),B("023","reading-comprehension","الحجامة من وسائل العلاج القديمة، وهي من أبرز ركائز الطب الصيني إلى جانب الإبر الصينية. ومع انتشار شركات الأدوية والأجهزة الطبية تراجعت شهرة الحجامة واستخدامها، وصار استعمال الأجهزة والأدوية أكثر شيوعًا، بالرغم من أن الحجامة أثبتت فائدتها علميًا. وتستخدم الحجامة لعلاج آلام العضلات والرأس وخدر الأطراف.\n\nما العلاقة بين الحجامة والأدوية كما يفهم من النص؟",["تنافسية","طردية","عكسية","سببية"],2,"مع ازدياد انتشار الأدوية والأجهزة تراجع استخدام الحجامة؛ فالعلاقة عكسية."),B("024","reading-comprehension","الحجامة من وسائل العلاج القديمة، وهي من أبرز ركائز الطب الصيني إلى جانب الإبر الصينية. ومع انتشار شركات الأدوية والأجهزة الطبية تراجعت شهرة الحجامة واستخدامها، وصار استعمال الأجهزة والأدوية أكثر شيوعًا، بالرغم من أن الحجامة أثبتت فائدتها علميًا. وتستخدم الحجامة لعلاج آلام العضلات والرأس وخدر الأطراف.\n\nما علاقة جملة «بالرغم من أن الحجامة أثبتت فائدتها علميًا» بما قبلها؟",["منافية","سبب","نتيجة","ترادف"],0,"العبارة تأتي على معنى الاستدراك والمخالفة لما قبلها، فهي منافية له."),B("025","reading-comprehension","الحجامة من وسائل العلاج القديمة، وهي من أبرز ركائز الطب الصيني إلى جانب الإبر الصينية. ومع انتشار شركات الأدوية والأجهزة الطبية تراجعت شهرة الحجامة واستخدامها، وصار استعمال الأجهزة والأدوية أكثر شيوعًا، بالرغم من أن الحجامة أثبتت فائدتها علميًا. وتستخدم الحجامة لعلاج آلام العضلات والرأس وخدر الأطراف.\n\nأي من العبارات الآتية لم تذكر في القطعة؟",["إن الحجامة وحدها من أبرز ركائز الطب الصيني","إن الحجامة تستخدم منذ القدم في الطب الصيني","قلة استخدام الناس للحجامة بسبب كثرة شراء الأدوية"],0,"النص يذكر الحجامة إلى جانب الإبر الصينية، لا أنها وحدها من أبرز ركائز الطب الصيني."),B("026","vocabulary","كل الكلمات الآتية بمعنى «ركائز» إلا:",["دعائم","أسس","أركان","أجزاء"],3,"«دعائم» و«أسس» و«أركان» مرادفات لركائز، أما «أجزاء» فليست مرادفًا مباشرًا."),B("027","reading-comprehension","الحجامة من وسائل العلاج القديمة، وهي من أبرز ركائز الطب الصيني إلى جانب الإبر الصينية. ومع انتشار شركات الأدوية والأجهزة الطبية تراجعت شهرة الحجامة واستخدامها، وصار استعمال الأجهزة والأدوية أكثر شيوعًا، بالرغم من أن الحجامة أثبتت فائدتها علميًا. وتستخدم الحجامة لعلاج آلام العضلات والرأس وخدر الأطراف.\n\nالحجامة تعالج:",["آلام المفاصل","حالات الخدور","تنظيف الدم من الشوائب","علاج آلام عضلات الرقبة"],3,"بحسب شرح السؤال في الفيديو، الخيار المحدد هو علاج آلام عضلات الرقبة، وهو داخل في آلام العضلات المذكورة في النص.")];})();
